export function renderRobotPicker(env){
 const {state,core:C,sprite,escape:esc,icon:I}=env,rows=state.robots.map(r=>C.robotInfo(state,r)),selected=rows.find(r=>r.uid===state.selectedRobot)||rows[0];
 return `<div class="robot-selector"><span class="field-title">SEU ROBÔ</span><details class="robot-picker"><summary>${selected?sprite(selected,'picker-portrait'):'<span class="picker-empty"></span>'}<span><b>${esc(selected?.name||'Escolha um robô')}</b><small>${selected?`NV. ${selected.level} · ${selected.power} poder`:'Adquira seu primeiro robô na oficina'}</small></span>${I('chevron')}</summary><input type="hidden" id="robot-selector" name="robot_id" value="${esc(selected?.uid||'')}"><div class="robot-picker-options" role="list">${rows.map(r=>`<button type="button" data-a="pick-robot" data-id="${esc(r.uid)}" class="${r.uid===selected?.uid?'selected':''}">${sprite(r,'picker-portrait')}<span><b>${esc(r.name)}</b><small>NV. ${r.level} · ${r.power} poder</small><em>${r.active?r.remainingBattles+' usos na arena':'Prazo encerrado'}</em></span>${r.uid===selected?.uid?I('check'):I('chevron')}</button>`).join('')||'<p class="picker-no-robots">Seu hangar ainda está vazio.</p>'}</div></details></div>`;
}
